def memberships(lang):
 en=lang=='en';p='/en/' if en else '/'
 if en:
  eyebrow='MEMBERSHIPS / KEEP SHOWING UP';title='Make training<br>part of your <em>life.</em>';desc='Explore membership options and find a rhythm that works for you.'
  h='Your next chapter starts here.';body='Contact the academy to confirm available memberships, class access, prices, and enrollment requirements.'
  status='Online enrollment is not available yet.';pending='For now, arrange your membership directly with the academy. No payment is collected on this website.';cta='Ask about memberships';portal='Already a member?';portaltxt='For billing changes, renewal questions, or cancellation requests, contact the academy.';manage='Contact the academy';waiver='Before your first class';waivertxt='Check the student waiver requirements, including the parent or guardian process for a minor.';waivercta='Student waiver';stephead='A clear path to the mat.';steps=[('Choose your membership','Confirm the class group and membership that fit your needs.'),('Complete your waiver','Review the academy’s waiver and follow the applicable signing process.'),('Start training','Confirm your enrollment and first class with the academy.')]
 else:
  eyebrow='MEMBRESÍAS / SIGUE PRESENTE';title='Haz del entrenamiento<br>parte de tu <em>vida.</em>';desc='Conoce las opciones de membresía y encuentra tu ritmo.'
  h='Tu siguiente etapa empieza aquí.';body='Contacta a la academia para confirmar las membresías disponibles, clases incluidas, precios y requisitos de inscripción.'
  status='La inscripción en línea aún no está disponible.';pending='Por ahora, tramita tu membresía directamente con la academia. Este sitio no cobra ningún pago.';cta='Consultar membresías';portal='¿Ya eres parte de la academia?';portaltxt='Para cambios de pago, dudas sobre renovación o solicitudes de cancelación, contacta a la academia.';manage='Contactar a la academia';waiver='Antes de tu primera clase';waivertxt='Consulta los requisitos de la carta responsiva, incluido el proceso para padres o tutores de menores de edad.';waivercta='Carta responsiva';stephead='Un camino claro al tatami.';steps=[('Elige tu membresía','Confirma el grupo y la membresía que se ajusten a tus necesidades.'),('Completa tu carta responsiva','Revisa el documento de la academia y sigue el proceso de firma correspondiente.'),('Empieza a entrenar','Confirma tu inscripción y primera clase con la academia.')]
 return head(lang,'Memberships' if en else 'Membresías','memberships/',desc)+header(lang,'memberships/')+f'''<main id="main"><section class="inner-hero"><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p>{desc}</p><a class="text-link" href="#membership-options">{'Explore options ↓' if en else 'Ver opciones ↓'}</a></section><section class="section enrollment-grid" id="membership-options"><div><p class="eyebrow">01 / {'YOUR MEMBERSHIP' if en else 'TU MEMBRESÍA'}</p><h2>{h}</h2><p>{body}</p><div id="plan-catalog"></div><div id="membership-pending" class="notice"><strong>{status}</strong><p>{pending}</p></div><a class="button dark" href="{wa(lang,'Hello, please send me your membership options, pricing, and renewal terms.' if en else 'Hola, ¿me comparten las opciones de membresía, precios y condiciones de renovación?')}" target="_blank" rel="noopener">{cta} ↗</a></div><aside class="member-aside"><div><p class="eyebrow">{'EXISTING STUDENTS' if en else 'ALUMNOS ACTUALES'}</p><h3>{portal}</h3><p id="portal-description">{portaltxt}</p><a id="member-portal" href="{wa(lang, "Hello, I am an existing student and need help with my membership." if en else "Hola, ya soy alumno y necesito ayuda con mi membresía.")}" target="_blank" rel="noopener">{manage} ↗</a></div><div><p class="eyebrow">{'NEW STUDENTS' if en else 'NUEVOS ALUMNOS'}</p><h3>{waiver}</h3><p>{waivertxt}</p><a href="{p}waiver/">{waivercta} →</a></div></aside></section><section class="section steps-section"><h2>{stephead}</h2><div class="enrollment-steps">'''+''.join(f'<article><span class="number">0{i+1}</span><h3>{a}</h3><p>{b}</p></article>' for i,(a,b) in enumerate(steps))+'''</div></section></main>'''+footer(lang)
def waiver(lang):
 en=lang=='en'
 eyebrow='NEW STUDENTS / BEFORE YOU TRAIN' if en else 'NUEVOS ALUMNOS / ANTES DE ENTRENAR'
 title='Your first step.<br><em>Your student waiver.</em>' if en else 'Tu primer paso.<br><em>Tu carta responsiva.</em>'
 desc='Find the right waiver process for an adult student or a parent or guardian.' if en else 'Encuentra el proceso de carta responsiva para alumnos adultos o padres y tutores.'
 return head(lang,'Student waiver' if en else 'Carta responsiva','waiver/',desc)+header(lang,'waiver/')+f'''<main id="main"><section class="inner-hero"><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p>{desc}</p></section><section class="section waiver-layout"><div><p class="eyebrow">01 / {'SELECT THE STUDENT' if en else 'SELECCIONA AL ALUMNO'}</p><h2>{'Who will be training?' if en else '¿Quién va a entrenar?'}</h2><fieldset class="student-selector"><legend>{'Student type' if en else 'Tipo de alumno'}</legend><label><input type="radio" name="student-type" value="adult" checked><span><strong>{'Adult student' if en else 'Alumno adulto'}</strong><small>{'18 years or older' if en else '18 años o más'}</small></span></label><label><input type="radio" name="student-type" value="minor"><span><strong>{'Minor student' if en else 'Alumno menor de edad'}</strong><small>{'Parent or guardian process' if en else 'Proceso para padre, madre o tutor'}</small></span></label></fieldset><div id="waiver-route" aria-live="polite"></div><div class="notice" id="waiver-pending"><strong>{'Online signing is not available yet.' if en else 'La firma en línea aún no está disponible.'}</strong><p>{'Contact the academy for its current waiver and signing instructions. No waiver has been signed or submitted on this page.' if en else 'Contacta a la academia para solicitar su carta responsiva vigente y las instrucciones de firma. En esta página no se ha firmado ni enviado ningún documento.'}</p></div><a id="waiver-start" class="button dark" hidden target="_blank" rel="noopener"></a><a id="waiver-inquiry" class="button dark" target="_blank" rel="noopener" href="{wa(lang)}">{'Request the waiver' if en else 'Solicitar carta responsiva'} ↗</a></div><aside class="waiver-aside"><span class="large-index">01—03</span><h3>{'Prepare for your first class.' if en else 'Prepárate para tu primera clase.'}</h3><ol><li>{'Choose the adult or minor student process.' if en else 'Selecciona el proceso para alumno adulto o menor de edad.'}</li><li>{'Request and read the academy’s current document.' if en else 'Solicita y lee el documento vigente de la academia.'}</li><li>{'Complete the required signatures before participation, following the academy’s instructions.' if en else 'Completa las firmas requeridas antes de participar, según las instrucciones de la academia.'}</li></ol><p>{'Questions about the document? Ask the academy before signing.' if en else '¿Tienes dudas sobre el documento? Consulta a la academia antes de firmar.'}</p></aside></section></main>'''+footer(lang)
